#include <cstring>
#include <cstdio>
#include <string>
#include <vector>
#include <iostream>

/// Mimic of CutURLParameterImpl::vector operating on a vector<char> buffer.
static void appendToResult(std::vector<char> & res_data, size_t & res_offset, const char * begin, const char * end)
{
    size_t length = end - begin;
    if (!length)
        return;
    res_data.resize(res_offset + length);
    memcpy(&res_data[res_offset], begin, length);
    res_offset += length;
}

static std::string cut(const std::string & url_str, std::string pattern)
{
    std::vector<char> data(url_str.begin(), url_str.end());
    data.push_back(0);
    std::vector<size_t> offsets{data.size()};
    std::vector<char> res_data;
    std::vector<size_t> res_offsets(1);

    pattern += '=';
    const char * param_str = pattern.c_str();
    size_t param_len = pattern.size();

    size_t prev_offset = 0;
    size_t res_offset = 0;

    for (size_t i = 0; i < offsets.size(); ++i)
    {
        size_t cur_offset = offsets[i];

        const char * url_begin = &data[prev_offset];
        const char * url_end = &data[0] + cur_offset - 1;

        const char * copy_pos = url_begin;

        const char * search_pos = url_begin;
        while (search_pos < url_end && *search_pos != '?' && *search_pos != '#')
            ++search_pos;
        if (search_pos != url_end)
            ++search_pos;

        while (search_pos < url_end)
        {
            const char * pos = static_cast<const char *>(memmem(search_pos, url_end - search_pos, param_str, param_len));
            if (pos == nullptr)
                break;

            if (pos[-1] != '?' && pos[-1] != '#' && pos[-1] != '&')
            {
                search_pos = pos + param_len;
                continue;
            }

            const char * begin_pos = pos;
            const char * end_pos = begin_pos + param_len;

            while (*end_pos && *end_pos != '&' && *end_pos != '#')
                ++end_pos;

            if (*end_pos == '&')
                ++end_pos;
            else if (begin_pos[-1] == '&')
            {
                if (begin_pos > copy_pos)
                    --begin_pos;
                else if (res_offset > 0 && res_data[res_offset - 1] == '&')
                    --res_offset;
            }

            appendToResult(res_data, res_offset, copy_pos, begin_pos);

            copy_pos = end_pos;
            search_pos = end_pos;
        }

        appendToResult(res_data, res_offset, copy_pos, url_end);

        res_data.resize(res_offset + 1);
        res_data[res_offset] = 0;
        ++res_offset;
        res_offsets[i] = res_offset;

        prev_offset = cur_offset;
    }

    return std::string(&res_data[0]);
}

int main()
{
    struct { const char * url; const char * name; } cases[] = {
        {"http://bigmir.net/?a=b&c=d", "a"},
        {"http://bigmir.net/?a=b&c=d", "c"},
        {"http://bigmir.net/?a=b&c=d#e=f", "e"},
        {"http://bigmir.net/?a=b&c=d#e=f&g=h", "g"},
        {"http://bigmir.net/?a=b&c=d#test?e=f&g=h", "test"},
        {"http://bigmir.net/?a=b&c=d#test?e=f&g=h", "e"},
        {"//bigmir.net/?a=b&c=d", "a"},
        {"http://bigmir.net/", "a"},
        {"", "a"},
        {"http://bigmir.net/?", "a"},
        {"http://bigmir.net/?a[]=1&a[]=2&b=3", "a[]"},
        {"http://bigmir.net/?a=1&b[]=2&b[]=3", "b[]"},
        {"http://bigmir.net/?a=1&b[]=2&b[]=3#c[]=4", "b[]"},
        {"http://bigmir.net/?a=1&b=2&a=3&c=4", "a"},
        {"http://bigmir.net/?ab=1&b=2", "b"},
        {"//bigmir.net/?a[]=1&a[]=2&a[]=3", "a[]"},
        {"http://bigmir.net/?a[]=1", "a[]"},
        {"http://bigmir.net/?a=1&b[]=2&x=3#b[]=4", "b[]"},
        {"http://bigmir.net/?a=1#b=2&b=3", "b"},
        {"http://bigmir.net/?b=1&b=2&a=3", "b"},
        {"http://bigmir.net/?a=1&b=2&b=3&b=4", "b"},
        {"http://bigmir.net/?a[]=1&a[]=2#a[]=3", "a[]"},
    };
    for (auto & c : cases)
        std::cout << "'" << c.url << "' / '" << c.name << "' -> '" << cut(c.url, c.name) << "'\n";
